# Dynamic active-neighbor fill: at each cell's v=r+c, find all segments whose continuous v intervals cover v, then fill only between neighboring active d values.
def predict_dynamic(input_grid, marked=None):
    H=len(input_grid); W=len(input_grid[0]);
    if marked is None: marked=set(x for row in input_grid for x in row if x!=8)
    pts=defaultdict(set)
    for r,row in enumerate(input_grid):
        for c,x in enumerate(row):
            if x in marked: pts[c-r].add((r,c))
    seg=[]
    for d,ps in pts.items():
        rr=sorted(r for r,c in ps); groups=[]
        for r in rr:
            if not groups or r>groups[-1][-1]+1: groups.append([r])
            else: groups[-1].append(r)
        for g in groups:
            vv=[2*r+d for r in g]
            seg.append((d,min(vv),max(vv),g))
    out=[row[:] for row in input_grid]
    for r in range(H):
        for c in range(W):
            d=c-r; v=c+r
            active=sorted(set(s[0] for s in seg if s[1]-1e-9<=v<=s[2]+1e-9))
            if any(a<d<b for a,b in zip(active,active[1:])) and out[r][c]==8:
                out[r][c]=2
    return seg,out
